import { describe, expect, it } from 'vitest';
import {
  MAX_BREAK,
  MAX_FOCUS,
  parseCreateSession,
  parseDeleteAccount,
  parseJoinSession,
  parseOnlineFriends,
  parseSendInvite,
  parseSessionReference,
  parseSetPet,
  parseShareInvite,
  parseStartSession,
} from './payloadParsers.js';

const AVATAR = {
  skinColor: '#F1C27D',
  hairStyle: 'bob',
  hairColor: '#3B2314',
  eyeStyle: 'normal',
  outfitColor: '#4A6FA5',
};

describe('account and social payload parsers', () => {
  it('requires the exact account-deletion phrase', () => {
    expect(parseDeleteAccount({ confirmation: 'DELETE' })).toEqual({
      ok: true,
      value: { confirmation: 'DELETE' },
    });
    expect(parseDeleteAccount({ confirmation: 'delete' })).toEqual({
      ok: false,
      reason: 'confirmation',
    });
  });

  it('bounds online-friend lookups to 100 string ids', () => {
    expect(parseOnlineFriends({ friendIds: ['a', 'b'] })).toEqual({
      ok: true,
      value: { friendIds: ['a', 'b'] },
    });
    expect(parseOnlineFriends({ friendIds: 'a' }).ok).toBe(false);
    expect(parseOnlineFriends({ friendIds: [null] }).ok).toBe(false);
    expect(parseOnlineFriends({ friendIds: Array(101).fill('a') }).ok).toBe(false);
  });

  it('requires an invite target and normalizes untrusted presentation fields', () => {
    expect(parseSendInvite({ targetUserId: '' }).ok).toBe(false);
    expect(parseSendInvite({
      targetUserId: 'friend',
      sessionId: 42,
      fromName: 42,
    })).toEqual({
      ok: true,
      value: {
        targetUserId: 'friend',
        sessionId: null,
        fromName: 'Someone',
      },
    });
  });
});

describe('session entry payload parsers', () => {
  it('sanitizes create-session identity fields and ignores unknown fields', () => {
    expect(parseCreateSession({
      avatar: AVATAR,
      displayName: 'x'.repeat(60),
      pet: 'griffin',
      world: 'space',
      petStage: 'full',
    })).toEqual({
      ok: true,
      value: {
        avatar: AVATAR,
        displayName: 'x'.repeat(50),
        pet: null,
        petName: null,
      },
    });
  });

  it.each([
    null,
    [],
    { ...AVATAR, skinColor: 'red' },
    { ...AVATAR, hairStyle: 'unknown' },
  ])('rejects invalid avatar %#', (avatar) => {
    expect(parseCreateSession({ avatar })).toEqual({
      ok: false,
      reason: 'avatar',
    });
  });

  it('accepts either a session id or a bounded bearer token when joining', () => {
    expect(parseJoinSession({ sessionId: 'room', avatar: AVATAR })).toEqual({
      ok: true,
      value: {
        sessionId: 'room',
        shareToken: null,
        joiningByLink: false,
        avatar: AVATAR,
        displayName: 'Player',
        pet: null,
        petName: null,
      },
    });
    expect(parseJoinSession({
      sessionId: 'ignored',
      shareToken: 'a'.repeat(20),
      avatar: AVATAR,
    }).value).toMatchObject({
      sessionId: null,
      shareToken: 'a'.repeat(20),
      joiningByLink: true,
    });
    expect(parseJoinSession({ shareToken: 'short', avatar: AVATAR })).toEqual({
      ok: false,
      reason: 'share_token',
    });
    expect(parseJoinSession({ avatar: AVATAR })).toEqual({
      ok: false,
      reason: 'session_id',
    });
  });

  it('requires a string session id for share invites', () => {
    expect(parseShareInvite({ sessionId: 'room' }).ok).toBe(true);
    expect(parseShareInvite({ sessionId: null })).toEqual({
      ok: false,
      reason: 'session_id',
    });
  });
});

describe('live-session payload parsers', () => {
  it('defaults and clamps timer settings at the protocol boundary', () => {
    expect(parseStartSession({ sessionId: 'room' }).value).toEqual({
      sessionId: 'room',
      focusDuration: 25 * 60,
      breakDuration: 5 * 60,
      mode: 'pomodoro',
    });
    expect(parseStartSession({
      sessionId: 'room',
      focusDuration: Infinity,
      breakDuration: -1,
      mode: 'flow',
    }).value).toEqual({
      sessionId: 'room',
      focusDuration: MAX_FOCUS,
      breakDuration: 30,
      mode: 'flow',
    });
  });

  it('parses session-only events without accepting coerced ids', () => {
    expect(parseSessionReference({ sessionId: 'room' }).ok).toBe(true);
    expect(parseSessionReference({ sessionId: 42 }).ok).toBe(false);
  });

  it('allowlists pets and treats an unknown pet as no pet', () => {
    expect(parseSetPet({ sessionId: 'room', pet: 'cat' }).value)
      .toEqual({ sessionId: 'room', pet: 'cat', petName: 'Mochi' });
    expect(parseSetPet({ sessionId: 'room', pet: 'griffin' }).value)
      .toEqual({ sessionId: 'room', pet: null, petName: null });
  });
});

const { companionName, normalizeCompanionName } = require('../shared/companionNames');
// Pure parsers for every client-originated Socket.IO payload. The transport
// boundary already rejects non-object containers; these functions validate and
// normalize fields without reading live session state or performing I/O.

const MAX_DISPLAY_NAME = 50;
const MAX_FOCUS = 120 * 60;
const MAX_BREAK = 60 * 60;

const VALID_HAIR_STYLES = ['bob', 'mohawk', 'long', 'spiky', 'bald'];
const VALID_EYE_STYLES = ['normal', 'anime', 'sleepy'];
const VALID_PETS = ['cat', 'dog', 'dragon', 'rabbit'];
const HEX_COLOR = /^#[0-9a-fA-F]{6}$/;

function valid(value) {
  return { ok: true, value };
}

function invalid(reason) {
  return { ok: false, reason };
}

function parsePet(pet) {
  return VALID_PETS.includes(pet) ? pet : null;
}

function parseDisplayName(displayName, fallback) {
  return (typeof displayName === 'string' ? displayName : fallback)
    .slice(0, MAX_DISPLAY_NAME);
}

function parseAvatar(avatar) {
  if (!avatar || typeof avatar !== 'object' || Array.isArray(avatar)) return null;
  const { skinColor, hairStyle, hairColor, eyeStyle, outfitColor } = avatar;
  if (!HEX_COLOR.test(skinColor) ||
      !HEX_COLOR.test(hairColor) ||
      !HEX_COLOR.test(outfitColor)) return null;
  if (!VALID_HAIR_STYLES.includes(hairStyle) ||
      !VALID_EYE_STYLES.includes(eyeStyle)) return null;
  return { skinColor, hairStyle, hairColor, eyeStyle, outfitColor };
}

function parseDeleteAccount(payload) {
  return payload.confirmation === 'DELETE'
    ? valid({ confirmation: 'DELETE' })
    : invalid('confirmation');
}

function parseOnlineFriends(payload) {
  const { friendIds } = payload;
  if (!Array.isArray(friendIds) || friendIds.length > 100 ||
      friendIds.some((id) => typeof id !== 'string')) {
    return invalid('friend_ids');
  }
  return valid({ friendIds });
}

function parseSendInvite(payload) {
  if (typeof payload.targetUserId !== 'string' || !payload.targetUserId) {
    return invalid('target_user_id');
  }
  return valid({
    targetUserId: payload.targetUserId,
    sessionId: typeof payload.sessionId === 'string' ? payload.sessionId : null,
    fromName: parseDisplayName(payload.fromName, 'Someone'),
  });
}

function parseCreateSession(payload) {
  const avatar = parseAvatar(payload.avatar);
  if (!avatar) return invalid('avatar');
  return valid({
    avatar,
    displayName: parseDisplayName(payload.displayName, 'Player'),
    pet: parsePet(payload.pet),
    petName: companionName(parsePet(payload.pet), payload.petName),
  });
}

function parseShareInvite(payload) {
  return typeof payload.sessionId === 'string'
    ? valid({ sessionId: payload.sessionId })
    : invalid('session_id');
}

function parseJoinSession(payload) {
  const avatar = parseAvatar(payload.avatar);
  if (!avatar) return invalid('avatar');

  const joiningByLink = typeof payload.shareToken === 'string';
  if (joiningByLink &&
      (payload.shareToken.length < 20 || payload.shareToken.length > 128)) {
    return invalid('share_token');
  }
  if (!joiningByLink && typeof payload.sessionId !== 'string') {
    return invalid('session_id');
  }

  return valid({
    sessionId: joiningByLink ? null : payload.sessionId,
    shareToken: joiningByLink ? payload.shareToken : null,
    joiningByLink,
    avatar,
    displayName: parseDisplayName(payload.displayName, 'Player'),
    pet: parsePet(payload.pet),
    petName: companionName(parsePet(payload.pet), payload.petName),
  });
}

function parseStartSession(payload) {
  if (typeof payload.sessionId !== 'string') return invalid('session_id');
  return valid({
    sessionId: payload.sessionId,
    focusDuration: Math.min(
      Math.max(Number(payload.focusDuration) || 25 * 60, 60),
      MAX_FOCUS,
    ),
    breakDuration: Math.min(
      Math.max(Number(payload.breakDuration) || 5 * 60, 30),
      MAX_BREAK,
    ),
    mode: payload.mode === 'flow' ? 'flow' : 'pomodoro',
  });
}

function parseSessionReference(payload) {
  return typeof payload.sessionId === 'string'
    ? valid({ sessionId: payload.sessionId })
    : invalid('session_id');
}

function parseSetPetName(payload) {
  const name = normalizeCompanionName(payload.name);
  if (typeof payload.sessionId !== 'string' || name === null) return invalid('companion_name');
  return valid({ sessionId: payload.sessionId, name });
}

function parseSetPet(payload) {
  if (typeof payload.sessionId !== 'string') return invalid('session_id');
  return valid({ sessionId: payload.sessionId, pet: parsePet(payload.pet), petName: companionName(parsePet(payload.pet), payload.petName) });
}

function parseSetIntention(payload) {
  if (typeof payload.sessionId !== 'string' || typeof payload.text !== 'string' || payload.text.length > 160) return invalid('intention');
  return valid({ sessionId: payload.sessionId, text: payload.text.replace(/\s+/g, ' ').trim() });
}
function parseResolveIntention(payload) {
  if (typeof payload.sessionId !== 'string' || !Number.isSafeInteger(payload.round) || payload.round < 1 ||
      !['done', 'undo', 'carry'].includes(payload.action)) return invalid('intention');
  return valid({ sessionId: payload.sessionId, round: payload.round, action: payload.action });
}

function parseReaction(payload) {
  if (typeof payload.sessionId !== 'string' || !['heart', 'cheer', 'wave'].includes(payload.reaction)) return invalid('reaction');
  return valid({ sessionId: payload.sessionId, reaction: payload.reaction });
}

module.exports = {
  parseReaction,
  parseSetIntention,
  parseResolveIntention,
  MAX_FOCUS,
  MAX_BREAK,
  parseDeleteAccount,
  parseOnlineFriends,
  parseSendInvite,
  parseCreateSession,
  parseShareInvite,
  parseJoinSession,
  parseStartSession,
  parseSessionReference,
  parseSetPet,
  parseSetPetName,
};

"""Visible pure-parser task checks; full server integration is outside this adapter."""

