                                          breakDuration: 300, mode: 'flow'}});
assert.equal(parseStartSession({sessionId: 'room',
  focusDuration: Infinity}).value.focusDuration, 7200);
""",
        ],
        capture_output=True,
        text=True,
        timeout=10,
        check=False,
    )
    assert result.returncode == 0, result.stderr[-4000:]

